local byId = {}
local byEnName = {}
for _, e in ipairs(EzWoWMapFinderData) do
  if e.kind == "npc" then
    if e.id then byId[e.id] = e end
    if e.names and e.names.enUS then byEnName[e.names.enUS] = e end
  end
end

local function regPet(id, enName, koName, famId, minL, maxL, spd, isRare, isElite, skills, zoneStr, spawns)
  if koName and koName ~= "" then
    EzWoWMapFinderTranslations.koKR.npc[id] = EzWoWMapFinderTranslations.koKR.npc[id] or koName
  end
  local e = byId[id] or (enName and byEnName[enName])
  if not e then
    e = { id = id, kind = "npc", names = { enUS = enName, koKR = koName }, flags = 0, spawns = spawns or {} }
    EzWoWMapFinderData[#EzWoWMapFinderData + 1] = e
    byId[id] = e
  else
    e.id = e.id or id
    byId[id] = e
    e.names = e.names or {}
    e.names.enUS = e.names.enUS or enName
    if koName and koName ~= "" then e.names.koKR = e.names.koKR or koName end
    if spawns and #spawns > 0 and (not e.spawns or #e.spawns == 0) then
      e.spawns = spawns
    end
  end
  e.isMonster = true
  e.isPet = true
  if isRare then e.isRare = true end
  if zoneStr and zoneStr ~= "" and not e.zone then e.zone = zoneStr end
  e.petInfo = { family = famId, minLvl = minL, maxLvl = maxL, speed = spd, skills = skills, elite = isElite }
end

